const FORMULA_SCALE = 400 / 1024 / 20;
const REPLAY_SCALE = 240 / 1024 / 20;

function GlyphRun({ run, x, y, scale }) {
  return run.map((entry, index) => (
    <path
      key={index}
      d={GLYPHS[entry.glyph]}
      fill="#000000"
      fillRule="evenodd"
      transform={
        "translate(" + (x + entry.x) + " " + y + ") scale(" + scale + ")"
      }
    />
  ));
}

export function FlashBauhausFormula({ opacity }) {
  return (
    <g opacity={opacity} role="img" aria-label="1 liter = 1000 milliliters">
      <GlyphRun
        run={FORMULA_RUN}
        x={147.65}
        y={161.55}
        scale={FORMULA_SCALE}
      />
    </g>
  );
}

export function FlashBauhausReplayText() {
  return (
    <g transform="translate(782.95 24) scale(1.3)">
      <GlyphRun run={REPLAY_RUN} x={-76.65} y={0.25} scale={REPLAY_SCALE} />
    </g>
  );
}
